import 'dart:async';import 'package:flutter/material.dart';import '../../core/auth/session_store.dart';import '../../core/network/api_client.dart';import '../../core/communication/communication_repository.dart';import '../../models/communication_models.dart';
class BookingChatScreen extends StatefulWidget{const BookingChatScreen({super.key,required this.bookingId,required this.bookingReference});final String bookingId,bookingReference;@override State<BookingChatScreen> createState()=>_BookingChatScreenState();}
class _BookingChatScreenState extends State<BookingChatScreen>{late final CommunicationRepository repo;final input=TextEditingController();List<BookingMessage> items=[];bool loading=true,sending=false;Timer? timer;@override void initState(){super.initState();repo=CommunicationRepository(ApiClient(SessionStore()));load();timer=Timer.periodic(const Duration(seconds:10),(_)=>load(silent:true));}@override void dispose(){timer?.cancel();input.dispose();super.dispose();}
 Future<void> load({bool silent=false})async{if(!silent&&mounted)setState(()=>loading=true);try{final x=await repo.messages(widget.bookingId);if(mounted)setState(()=>items=x);}finally{if(mounted)setState(()=>loading=false);}}
 Future<void> send()async{final text=input.text.trim();if(text.isEmpty||sending)return;setState(()=>sending=true);try{final x=await repo.send(widget.bookingId,text);input.clear();setState(()=>items=[...items,x]);}finally{if(mounted)setState(()=>sending=false);}}
 @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text('Trip chat · ${widget.bookingReference}')),body:Column(children:[Expanded(child:loading?const Center(child:CircularProgressIndicator()):ListView(padding:const EdgeInsets.all(14),children:items.map((m)=>Align(alignment:m.isMine?Alignment.centerRight:Alignment.centerLeft,child:Container(margin:const EdgeInsets.only(bottom:8),padding:const EdgeInsets.symmetric(horizontal:13,vertical:10),constraints:BoxConstraints(maxWidth:MediaQuery.sizeOf(c).width*.78),decoration:BoxDecoration(color:m.isMine?Theme.of(c).colorScheme.primary:Colors.white,borderRadius:BorderRadius.circular(16),border:m.isMine?null:Border.all(color:Colors.black12)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[if(!m.isMine)Text(m.senderName,style:const TextStyle(fontSize:10,fontWeight:FontWeight.w800)),Text(m.body,style:TextStyle(color:m.isMine?Colors.white:null)),const SizedBox(height:3),Text('${m.sentAt.toLocal().hour.toString().padLeft(2,'0')}:${m.sentAt.toLocal().minute.toString().padLeft(2,'0')}',style:TextStyle(fontSize:9,color:m.isMine?Colors.white70:Colors.black45))])))).toList())),SafeArea(child:Padding(padding:const EdgeInsets.all(10),child:Row(children:[Expanded(child:TextField(controller:input,maxLength:2000,decoration:const InputDecoration(counterText:'',hintText:'Write a trip message…'))),const SizedBox(width:8),IconButton.filled(onPressed:sending?null:send,icon:const Icon(Icons.send_rounded))])))]));}
